+import { useRef, useState, useCallback } from 'react';
+
+export function VirtualList({ items, itemHeight, renderItem }) {
+  const containerRef = useRef<HTMLDivElement>(null);
+  const [scrollTop, setScrollTop] = useState(0);
+
+  const handleScroll = useCallback(() => {
+    setScrollTop(containerRef.current?.scrollTop ?? 0);
+  }, []);
+
+  const startIndex = Math.floor(scrollTop / itemHeight);
+  const endIndex = startIndex + Math.ceil(500 / itemHeight);
+  const visibleItems = items.slice(startIndex, endIndex);
+
+  return (
+    <div ref={containerRef} onScroll={handleScroll} style={{ height: 500, overflow: 'auto' }}>
+      <div style={{ height: items.length * itemHeight }}>
+        {visibleItems.map((item, i) => (
+          <div key={item.id} style={{ position: 'absolute', top: (startIndex + i) * itemHeight }}>
+            {renderItem(item)}
+          </div>
+        ))}
+      </div>
+    </div>
+  );
+}
